with filtered as (select *, round(cost, 2) as cost_rounded, coalesce(carrier, 'UNKNOWN') as carrier_clean from shipments where shipped_date > date '2023-06-30' and order_id is not null), ranked as (select * from (select *, row_number() over (partition by order_id, carrier order by cost_rounded desc nulls last, id) as rn from filtered) ranked where rn = 1), metrics as (select *, last_value(cost_rounded) ignore nulls over (partition by status order by cost_rounded, id rows between unbounded preceding and current row) as last_known_cost_rounded, lead(cost, 1) over w_part as next_cost, ntile(5) over (partition by order_id order by cost_rounded desc, id) as cost_rounded_bucket, row_number() over w_part as seq_no from ranked window w_part as (order by cost, id)), enriched as (select e.*, o.shipping_fee, o.amount, o.status as order_status from metrics e inner join orders o on e.order_id = o.id), with_windows as (select *, lag(cost, 1, 0) over (partition by status, carrier order by shipped_date, id) as prev_cost, dense_rank() over (order by cost_rounded) as cost_rounded_dense_rank from enriched) select id, order_id, carrier, cost, status, cost_rounded, carrier_clean, rn, last_known_cost_rounded from with_windows
